from time import time, sleep
from functools import wraps

ip_request_count = {}

def rate_limit(max_requests_per_second):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            ip_address = kwargs.get('ip_address')
            if ip_address not in ip_request_count:
                ip_request_count[ip_address] = []

            now = time()
            ip_request_count[ip_address] = [t for t in ip_request_count[ip_address] if now - t < 1]

            if len(ip_request_count[ip_address]) >= max_requests_per_second:
                raise Exception("Rate limit exceeded")

            ip_request_count[ip_address].append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

import unittest

class TestRateLimit(unittest.TestCase):
    @rate_limit(5)
    def test_function(self, ip_address):
        return "Hello, World!"

    def test_rate_limit(self):
        for _ in range(5):
            self.test_function(ip_address="127.0.0.1")
        with self.assertRaises(Exception):
            self.test_function(ip_address="127.0.0.1")

if __name__ == "__main__":
    unittest.main()
```

